WITH valid AS (SELECT *, CASE WHEN salary >= 125000 THEN 'High' WHEN salary >= 73000 THEN 'Medium' ELSE 'Low' END AS salary_band, COALESCE(job_title, 'NONE') AS job_title_filled FROM employees WHERE hire_date >= DATE '2023-06-25' AND manager_id IS NOT NULL AND job_title = 'Intern'), with_windows AS (SELECT *, AVG(salary) OVER (PARTITION BY job_title ORDER BY salary, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS salary_avg_3, NTILE(10) OVER w_part AS salary_bucket, LAST_VALUE(job_title, TRUE) OVER (ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_job_title FROM valid WINDOW w_part AS (PARTITION BY job_title, level ORDER BY salary, id)), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC, id) AS rank_in_group FROM with_windows QUALIFY rank_in_group = 1), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY job_title ORDER BY rank_in_group, id) AS row_num FROM ranked QUALIFY row_num = 1), enriched AS (SELECT *, ROUND(salary_bucket / SUM(salary_bucket) OVER (PARTITION BY level), 4) AS salary_bucket_share, NTILE(5) OVER (PARTITION BY dept_id ORDER BY salary_avg_3 DESC, id) AS salary_avg_3_bucket, SUM(salary_avg_3) OVER (ORDER BY rank_in_group, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_salary_avg_3, SUM(salary_avg_3) OVER (PARTITION BY manager_id ORDER BY salary_avg_3, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_salary_avg_3_2 FROM latest), joined AS (SELECT e.*, p.dept_name, p.location, p.budget FROM enriched e LEFT JOIN departments p ON e.dept_id = p.id), cleaned AS (SELECT id, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, salary_band, job_title_filled, salary_avg_3, salary_bucket, last_known_job_title, row_num, salary_bucket_share, running_salary_avg_3_2, dept_name, location, COALESCE(salary_bucket_share, 0) AS salary_bucket_share_filled FROM joined WHERE level IS NOT NULL), totals AS (SELECT manager_id, SIZE(COLLECT_SET(job_title)) AS num_job_titles, AVG(salary_bucket_share) AS avg_salary_bucket_share, ROUND(SUM(salary_bucket_share) / NULLIF(COUNT(CASE WHEN job_title = 'Analyst' THEN 1 END), 0), 2) AS salary_bucket_share_per_analyst, COUNT(*) FILTER (WHERE location = 'Singapore') AS singapore_rows, SUM(salary_bucket_share) FILTER (WHERE level = 'L5') AS l5_total_salary_bucket_share, SIZE(COLLECT_SET(level)) AS num_levels FROM cleaned GROUP BY manager_id) SELECT manager_id, num_job_titles, avg_salary_bucket_share FROM totals ORDER BY avg_salary_bucket_share DESC NULLS LAST;
